"use client";

import { useState } from "react";
import { GlassPanel } from "@/components/custom/blocks/GlassPanelBlock";
import { ProfilePage, WorkdayDial } from "@/components/custom/blocks/ProfilePageBlock";
import { SocialLinks } from "@/components/custom/blocks/SocialLinksBlock";
import { VerifyBadge } from "@/components/custom/blocks/VerifyBadgeBlock";
import { cn } from "@/lib/utils";
import {
  ArrowLeft,
  Check,
  Eye,
  FileText,
  GitMerge,
  Globe,
  Mail,
  MapPin,
  MessageCircle,
  Share2,
  UserPlus,
} from "lucide-react";

const TIME_ZONE = "Asia/Dhaka";
const WORKDAY = { start: 10, end: 18 };

const STATS = [
  { value: "116", label: "Components" },
  { value: "317", label: "PRs merged" },
  { value: "88", label: "Code reviews" },
];

const SKILLS = ["Component APIs", "React", "Animation", "Accessibility", "TypeScript", "Figma"];

const HIGHLIGHTS = [
  {
    title: "Animation toolkit 2.0",
    summary: "A shared set of easings for dialogs, sheets and toasts.",
    status: "In progress",
    progress: 68,
  },
  {
    title: "Brightmoor Kit 4",
    summary: "116 components, a dark theme out of the box, CSS-variable tokens.",
    status: "Released June 2026",
  },
  {
    title: "Colour contrast review",
    summary: "All text and icons verified against a 4.5:1 minimum ratio.",
    status: "Released February 2026",
  },
];

const TEAMMATES = [
  { initials: "MD", name: "Mateo Duarte", role: "Prototypes and animation", zone: "Lisbon", tint: "bg-sky-500/15 text-sky-800 dark:text-sky-200" },
  { initials: "IO", name: "Ifeoma Okafor", role: "Inclusive design", zone: "Lagos", tint: "bg-amber-500/15 text-amber-800 dark:text-amber-200" },
  { initials: "KI", name: "Kavya Iyer", role: "Design tokens", zone: "Pune", tint: "bg-rose-500/15 text-rose-800 dark:text-rose-200" },
];

const ACTIVITY = [
  { icon: GitMerge, text: "Merged #1311, one shared easing for every overlay", when: "2h ago" },
  { icon: Eye, text: "Reviewed Mateo's sheet focus-trap patch", when: "Yesterday" },
  { icon: FileText, text: "Posted the changelog for Brightmoor Kit 4", when: "3 days ago" },
  { icon: MessageCircle, text: "Started an RFC about naming tokens", when: "Last week" },
];

const focusRing =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background";

export default function ProfilePageDemo() {
  const [following, setFollowing] = useState(false);

  return (
    <ProfilePage aurora={["var(--primary)", "#7dd3fc", "#fdba74"]} className="min-h-dvh">
      {/* Hero */}
      <GlassPanel shape="slab" className="flex flex-col gap-6 p-6 sm:p-8 md:col-span-6 lg:col-span-8">
        <div className="flex items-center justify-between">
          <a
            href="#"
            className={cn(
              "inline-flex items-center gap-1.5 rounded-full text-sm text-foreground/60 transition-colors hover:text-foreground",
              focusRing,
            )}
          >
            <ArrowLeft className="size-4" /> Directory
          </a>
          <button
            type="button"
            className={cn(
              "inline-flex size-10 items-center justify-center rounded-full border border-foreground/10 bg-foreground/[0.04] text-foreground/70 transition-colors hover:bg-foreground/[0.08]",
              focusRing,
            )}
            aria-label="Share profile"
          >
            <Share2 className="size-4" />
          </button>
        </div>

        <div className="flex flex-col gap-5 sm:flex-row sm:items-center">
          {/* Squircle avatar — the only shape on the page that isn't a
              rectangle, circle or capsule, so it reads as the person */}
          <div className="relative shrink-0">
            <span className="grid size-24 place-items-center rounded-[30%] bg-gradient-to-br from-primary to-primary/70 text-3xl font-semibold text-primary-foreground shadow-[0_16px_32px_-16px_var(--primary)] sm:size-28 sm:text-4xl">
              FH
            </span>
          </div>
          <div className="min-w-0">
            <h1 className="flex flex-wrap items-center gap-2.5 text-3xl font-semibold tracking-tight sm:text-[40px] sm:leading-none">
              Farah Haque
              <VerifyBadge size="lg" aria-label="Verified" />
            </h1>
            <p className="mt-2 text-base text-foreground/60">
              UI engineer at Brightmoor
            </p>
            <ul className="mt-3 flex flex-wrap gap-x-4 gap-y-1 text-sm text-foreground/60">
              <li className="flex items-center gap-1.5">
                <MapPin className="size-3.5" /> Dhaka
              </li>
              <li className="flex items-center gap-1.5">
                <Mail className="size-3.5" /> farah@brightmoor.io
              </li>
              <li className="flex items-center gap-1.5">
                <Globe className="size-3.5" /> farahhaque.dev
              </li>
            </ul>
            <SocialLinks
              size="sm"
              variant="ghost"
              className="mt-3 -ml-2 gap-0.5"
              links={[
                { network: "x", href: "https://x.com", label: "Farah on X" },
                { network: "github", href: "https://github.com", label: "Farah on GitHub" },
                { network: "dribbble", href: "https://dribbble.com", label: "Farah on Dribbble" },
              ]}
            />
          </div>
        </div>

        {/* Action capsule */}
        <div className="mt-auto flex flex-wrap gap-2">
          <button
            type="button"
            aria-pressed={following}
            onClick={() => setFollowing((v) => !v)}
            className={cn(
              "inline-flex h-9 items-center gap-1.5 rounded-full px-4 text-[13px] font-medium transition-colors sm:h-11 sm:gap-2 sm:px-5 sm:text-sm",
              following
                ? "border border-foreground/10 bg-foreground/[0.04] text-foreground hover:bg-foreground/[0.08]"
                : "bg-primary text-primary-foreground hover:bg-primary/90",
              focusRing,
            )}
          >
            {following ? <Check className="size-3.5 sm:size-4" /> : <UserPlus className="size-3.5 sm:size-4" />}
            {following ? "Following" : "Follow"}
          </button>
          <button
            type="button"
            className={cn(
              "inline-flex h-9 items-center gap-1.5 rounded-full border border-foreground/10 bg-foreground/[0.04] px-4 text-[13px] font-medium transition-colors hover:bg-foreground/[0.08] sm:h-11 sm:gap-2 sm:px-5 sm:text-sm",
              focusRing,
            )}
          >
            <MessageCircle className="size-3.5 sm:size-4" /> Message
          </button>
        </div>
      </GlassPanel>

      {/* Her schedule */}
      <GlassPanel shape="slab" className="flex flex-col p-6 md:col-span-6 lg:col-span-4">
        <div className="flex items-baseline justify-between">
          <h2 className="text-sm font-semibold">Her schedule</h2>
          <p className="text-xs text-foreground/50">UTC+6</p>
        </div>
        <div className="my-auto py-4">
          <WorkdayDial
            timeZone={TIME_ZONE}
            start={WORKDAY.start}
            end={WORKDAY.end}
            place="Dhaka"
            name="Farah"
            note="Usually answers the same day"
          />
        </div>
        <p className="text-center text-sm text-foreground/60">
          Point at the ring to see her hours in your zone
        </p>
      </GlassPanel>

      {/* Stat discs */}
      <div className="grid grid-cols-3 gap-4 md:col-span-6 lg:col-span-4">
        {STATS.map((s) => (
          <GlassPanel key={s.label} shape="disc" className="grid place-items-center text-center">
            <div>
              <p className="text-2xl font-semibold tabular-nums tracking-tight sm:text-3xl">{s.value}</p>
              <p className="mt-0.5 text-[11px] text-foreground/55 sm:text-xs">{s.label}</p>
            </div>
          </GlassPanel>
        ))}
      </div>

      {/* About */}
      <GlassPanel className="flex flex-col gap-4 p-6 md:col-span-6 lg:col-span-8">
        <h2 className="text-sm font-semibold">About</h2>
        <p className="max-w-prose text-[15px] leading-relaxed text-foreground/70">
          Maintains the shared UI kit that three product squads build on. Right
          now reworking the animation toolkit so dialogs, sheets and toasts all
          move on one curve. Loves turning a design choice into a single token.
        </p>
        <ul className="flex flex-wrap gap-2">
          {SKILLS.map((skill) => (
            <li
              key={skill}
              className="rounded-full border border-foreground/10 bg-foreground/[0.04] px-3 py-1 text-xs"
            >
              {skill}
            </li>
          ))}
        </ul>
      </GlassPanel>

      {/* Highlights — three tiles, each its own panel */}
      {HIGHLIGHTS.map((item) => (
        <GlassPanel key={item.title} className="flex flex-col gap-3 p-5 md:col-span-2 lg:col-span-4">
          <div className="space-y-1">
            <p className="text-sm font-semibold leading-snug">{item.title}</p>
            <p className="text-xs leading-relaxed text-foreground/60">{item.summary}</p>
          </div>
          <div className="mt-auto space-y-2">
            {item.progress !== undefined && (
              <div
                role="progressbar"
                aria-valuenow={item.progress}
                aria-valuemin={0}
                aria-valuemax={100}
                aria-label={`${item.title} progress`}
                className="h-1.5 overflow-hidden rounded-full bg-foreground/10"
              >
                <div
                  className="h-full rounded-full bg-primary"
                  style={{ width: `${item.progress}%` }}
                />
              </div>
            )}
            <p
              className={cn(
                "text-xs font-medium",
                item.progress !== undefined
                  ? "text-primary"
                  : "text-foreground/50",
              )}
            >
              {item.status}
            </p>
          </div>
        </GlassPanel>
      ))}

      {/* Team */}
      <GlassPanel className="flex flex-col gap-4 p-6 md:col-span-3 lg:col-span-5">
        <h2 className="text-sm font-semibold">Frequent collaborators</h2>
        <ul className="flex flex-col gap-3">
          {TEAMMATES.map((m) => (
            <li key={m.name} className="flex items-center gap-3">
              <span className={cn("grid size-10 shrink-0 place-items-center rounded-[30%] text-xs font-semibold", m.tint)}>
                {m.initials}
              </span>
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-medium">{m.name}</p>
                <p className="truncate text-xs text-foreground/55">{m.role}</p>
              </div>
              <span className="shrink-0 text-xs text-foreground/50">{m.zone}</span>
            </li>
          ))}
        </ul>
      </GlassPanel>

      {/* Activity */}
      <GlassPanel className="flex flex-col gap-4 p-6 md:col-span-3 lg:col-span-7">
        <h2 className="text-sm font-semibold">Recent activity</h2>
        <ol className="flex flex-col divide-y divide-foreground/[0.07]">
          {ACTIVITY.map((a) => (
            <li key={a.text} className="flex items-center gap-3 py-2.5 first:pt-0 last:pb-0">
              <span className="grid size-8 shrink-0 place-items-center rounded-full bg-foreground/[0.06] text-foreground/60">
                <a.icon className="size-3.5" />
              </span>
              <p className="min-w-0 flex-1 truncate text-sm">{a.text}</p>
              <span className="shrink-0 text-xs text-foreground/50">{a.when}</span>
            </li>
          ))}
        </ol>
      </GlassPanel>
    </ProfilePage>
  );
}

"use client";

import { cn } from "@/lib/utils";
import React from "react";
import {
  LiquidGlassSvgFilter,
  LiquidGlassWrapper,
  formatRadius,
} from "@/components/custom/ui/liquid-glass";
import { SurfaceContext, useSurface, type SurfaceVariant } from "./glass-panel-context";

// The surface context and its hook, `useSurface`, live in glass-panel-context.ts.
export type { SurfaceVariant };

// ==========================================
// 1. GLASS BACKDROP — aurora ground + bento grid
// ==========================================
// The surface the panels sit on. Profile Page, Book Appointment and Booking
// Card all build on this pair; it has no opinion about what the page is.

export interface GlassBackdropProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Frosted glass over an aurora, solid cards with a shadow, or liquid-glass refraction. */
  variant?: SurfaceVariant;
  /**
   * Three colours washed behind the glass, top-left / top-right / bottom.
   * Any CSS colour. The defaults are violet, sky and peach. Ignored by `solid`.
   */
  aurora?: [string, string, string];
  /** Optional custom background image URL for liquid-glass variant. */
  bgImage?: string;
  /** Classes for the inner grid — row heights, gaps, a max width. */
  gridClassName?: string;
  /** Classes for the inner LiquidGlassWrapper — controls width ratio on large screens. */
  wrapperClassName?: string;
  /** Dynamic rounding radius for the wrapper/backdrop. Can be a string ("1.5rem", "var(--radius-3xl)") or number (px). */
  radius?: string | number;
}

export function GlassBackdrop({
  className,
  gridClassName,
  wrapperClassName,
  radius,
  children,
  variant = "glass",
  aurora = ["#a78bfa", "#7dd3fc", "#fdba74"],
  bgImage,
  ...props
}: GlassBackdropProps) {
  if (variant === "liquid-glass") {
    const liquidBg =
      bgImage ||
      "https://res.cloudinary.com/dodndg7ai/image/upload/f_webp,q_auto,w_1600,c_limit/v1790146209/photo-1470071459604-3b5ec3a7fe05-1790146212205.jpg";
    const filterId = "glass-blur-profile";

    return (
      <SurfaceContext.Provider value={variant}>
        <div
          className={cn(
            "relative isolate w-full h-full min-h-[520px] flex flex-col justify-center overflow-hidden rounded-[var(--radius-3xl,2rem)] border border-white/10 text-white p-3 sm:p-6",
            className,
          )}
          {...props}
        >
          {/* Full-bleed background image - spans 100% width and height of outer container, completely unwrapped */}
          <LiquidGlassSvgFilter id={filterId} bgImage={liquidBg} />
          <img
            src={liquidBg}
            alt=""
            aria-hidden="true"
            style={radius ? { borderRadius: formatRadius(radius) } : undefined}
            className="absolute inset-0 w-full h-full object-cover select-none pointer-events-none z-0 rounded-[inherit]"
          />

          {/* LiquidGlassWrapper wraps ONLY the component grid area */}
          <LiquidGlassWrapper
            radius={radius ?? "var(--radius-3xl, 1.75rem)"}
            bgImage={liquidBg}
            filterId={filterId}
            contrastOverlayClassName="bg-black/15 backdrop-blur-[1px]"
            className={cn(
              "relative z-10 w-full lg:w-[40%] lg:max-w-[40%] mx-auto text-white transition-all duration-300 p-1 sm:p-2 [--foreground:#ffffff] [--muted-foreground:rgba(255,255,255,0.85)]",
              wrapperClassName,
            )}
          >
            <div
              className={cn(
                "grid grid-cols-1 gap-4 md:grid-cols-6 lg:grid-cols-12 text-white",
                gridClassName,
              )}
            >
              {children}
            </div>
          </LiquidGlassWrapper>
        </div>
      </SurfaceContext.Provider>
    );
  }

  return (
    <SurfaceContext.Provider value={variant}>
      <div
        className={cn(
          "relative isolate w-full overflow-hidden bg-background text-foreground",
          className,
        )}
        {...props}
      >
        {/* The blobs are what the glass blurs. They sit still — the only thing
          that moves on this page is the live marker on the dial. */}
        {variant === "glass" && (
          <div
            aria-hidden
            className="pointer-events-none absolute inset-0 -z-10"
          >
            <span
              style={{ background: aurora[0] }}
              className="absolute -left-32 -top-32 size-[32rem] rounded-full opacity-80 blur-3xl dark:opacity-35"
            />
            <span
              style={{ background: aurora[1] }}
              className="absolute -right-24 top-16 size-[28rem] rounded-full opacity-80 blur-3xl dark:opacity-35"
            />
            <span
              style={{ background: aurora[2] }}
              className="absolute -bottom-40 left-1/3 size-[32rem] rounded-full opacity-70 blur-3xl dark:opacity-30"
            />
          </div>
        )}

        <div className={cn("grid grid-cols-1 gap-4 p-4 sm:p-6 md:grid-cols-6 lg:grid-cols-12", gridClassName)}>
          {children}
        </div>
      </div>
    </SurfaceContext.Provider>
  );
}

// ==========================================
// 2. GLASS PANEL — one recipe, four shapes
// ==========================================
export type GlassShape = "slab" | "tile" | "disc" | "capsule";

const SHAPES: Record<GlassShape, string> = {
  /** Hero-level surface. */
  slab: "rounded-[var(--radius-3xl,2rem)]",
  /** Everyday content tile. */
  tile: "rounded-[var(--radius-2xl,1.5rem)]",
  /** A circle — for a single number or an icon. */
  disc: "aspect-square rounded-full",
  /** Chips, action bars, anything one line tall. */
  capsule: "rounded-full",
};

export interface GlassPanelProps extends React.HTMLAttributes<HTMLDivElement> {
  shape?: GlassShape;
  /** Lifts on hover and shows a pointer — for panels that open something. */
  interactive?: boolean;
  /** Override the surface set by the enclosing `GlassBackdrop`. */
  variant?: SurfaceVariant;
  /** Optional custom rounding radius override. */
  radius?: string | number;
}

const SURFACES: Record<SurfaceVariant, { base: string; hover: string }> = {
  glass: {
    base:
      "border border-card/70 bg-card/55 shadow-[inset_0_1px_0_rgba(255,255,255,0.75),0_24px_48px_-28px_rgba(15,23,42,0.35)] backdrop-blur-2xl " +
      "dark:border-foreground/10 dark:bg-foreground/[0.06] dark:shadow-[inset_0_1px_0_rgba(255,255,255,0.08),0_24px_48px_-28px_rgba(0,0,0,0.9)]",
    hover: "hover:bg-card/70 dark:hover:bg-foreground/[0.09]",
  },
  solid: {
    base:
      "border border-border bg-card shadow-[0_1px_2px_rgba(0,0,0,0.04),0_16px_40px_-20px_rgba(15,23,42,0.25)] " +
      "dark:shadow-[0_1px_2px_rgba(0,0,0,0.4),0_16px_40px_-20px_rgba(0,0,0,0.9)]",
    hover:
      "hover:shadow-[0_1px_2px_rgba(0,0,0,0.04),0_24px_48px_-20px_rgba(15,23,42,0.3)]",
  },
  "liquid-glass": {
    base:
      "border border-white/35 bg-white/15 text-white shadow-[0_8px_32px_rgba(0,0,0,0.15),inset_0_1px_1px_rgba(255,255,255,0.5)]",
    hover: "hover:bg-white/25 hover:border-white/50",
  },
};

export function GlassPanel({
  shape = "tile",
  interactive = false,
  variant,
  radius,
  className,
  style,
  children,
  ...props
}: GlassPanelProps) {
  const inherited = useSurface();
  const surface = SURFACES[variant ?? inherited];
  const formattedRadius = formatRadius(radius);
  return (
    <div
      style={formattedRadius ? { borderRadius: formattedRadius, ...style } : style}
      className={cn(
        "relative",
        surface.base,
        SHAPES[shape],
        interactive &&
          cn(
            "cursor-pointer transition-[transform,background-color,box-shadow] duration-200 hover:-translate-y-0.5 motion-reduce:transition-none motion-reduce:hover:translate-y-0",
            surface.hover,
          ),
        className,
      )}
      {...props}
    >
      {children}
    </div>
  );
}

"use client";

import { createContext, useContext } from "react";

/**
 * The page's surface treatment. `glass` is frosted panels over an aurora;
 * `solid` is plain theme cards with an ordinary shadow on a flat ground.
 */
export type SurfaceVariant = "glass" | "solid" | "liquid-glass";

/** Set by `GlassBackdrop` for every `GlassPanel` inside it. */
export const SurfaceContext = createContext<SurfaceVariant>("glass");

/** The surface variant of the enclosing `GlassBackdrop`. */
export const useSurface = () => useContext(SurfaceContext);

"use client";

import React from "react";
import { cn } from "@/lib/utils";

export interface LiquidGlassSvgFilterProps {
  id?: string;
  baseFrequency?: string;
  scale?: number;
  bgImage?: string;
}

export function LiquidGlassSvgFilter({
  id = "glass-blur-ai",
  baseFrequency = "0.003 0.007",
  scale = 200,
  bgImage = "https://res.cloudinary.com/dodndg7ai/image/upload/f_webp,q_auto,w_1200,c_limit/v1790146209/photo-1470071459604-3b5ec3a7fe05-1790146212205.jpg",
}: LiquidGlassSvgFilterProps) {
  return (
    <>
      {bgImage && (
        <img
          src={bgImage}
          alt=""
          aria-hidden="true"
          style={{
            position: "fixed",
            top: "-9999px",
            left: "-9999px",
            width: "1px",
            height: "1px",
            opacity: 0,
            pointerEvents: "none",
          }}
        />
      )}
      <svg
        style={{
          position: "fixed",
          top: "-9999px",
          left: "-9999px",
          width: 0,
          height: 0,
          pointerEvents: "none",
        }}
        aria-hidden="true"
      >
        <defs>
          <filter
            id={id}
            x="-20%"
            y="-20%"
            width="140%"
            height="140%"
            filterUnits="objectBoundingBox"
          >
            <feTurbulence
              type="fractalNoise"
              baseFrequency={baseFrequency}
              numOctaves="1"
              result="turbulence"
            />
            <feDisplacementMap
              in="SourceGraphic"
              in2="turbulence"
              scale={scale}
              xChannelSelector="R"
              yChannelSelector="G"
            />
          </filter>
        </defs>
      </svg>
    </>
  );
}

export function formatRadius(radius?: string | number | boolean): string | undefined {
  if (radius === undefined || radius === null) return undefined;
  if (radius === false || radius === 0 || radius === "0" || radius === "0px") return "0px";
  if (typeof radius === "number") return `${radius}px`;
  if (typeof radius === "string") {
    if (
      radius.endsWith("px") ||
      radius.endsWith("rem") ||
      radius.endsWith("em") ||
      radius.endsWith("%") ||
      radius.includes("var(") ||
      radius.includes("calc(")
    ) {
      return radius;
    }
    const parsed = parseFloat(radius);
    if (!isNaN(parsed)) {
      return `${parsed}px`;
    }
  }
  return undefined;
}

export interface LiquidGlassBackgroundProps {
  className?: string;
  style?: React.CSSProperties;
  /**
   * Dynamic rounding radius. Can be a number (in px), a CSS length string ("16px", "1.5rem"),
   * or omitted to inherit the border-radius set on the parent/wrapper component.
   */
  radius?: string | number | boolean;
  bgImage?: string;
  filterId?: string;
  showSpecularHighlight?: boolean;
  contrastOverlayClassName?: string;
  bgPosition?: string;
  showOuterShadow?: boolean;
  shadowStyle?: React.CSSProperties;
}

export function LiquidGlassBackground({
  className,
  style,
  radius,
  bgImage = "https://res.cloudinary.com/dodndg7ai/image/upload/f_webp,q_auto,w_1200,c_limit/v1790146209/photo-1470071459604-3b5ec3a7fe05-1790146212205.jpg",
  filterId = "glass-blur-ai",
  showSpecularHighlight = true,
  contrastOverlayClassName = "bg-black/30 dark:bg-black/45 backdrop-blur-[2px]",
  bgPosition = "center",
  showOuterShadow = true,
  shadowStyle,
}: LiquidGlassBackgroundProps) {
  const formattedRadius = formatRadius(radius);

  const bgStyle: React.CSSProperties = {
    ...(formattedRadius ? { borderRadius: formattedRadius } : {}),
    ...style,
  };

  return (
    <div
      style={bgStyle}
      className={cn(
        "absolute inset-0 pointer-events-none z-0 rounded-[inherit] overflow-hidden isolate [contain:paint] [transform:translateZ(0)]",
        className
      )}
    >
      {/* Inner Clipping Container for Liquid Background Stack */}
      <div
        className="absolute inset-0 overflow-hidden rounded-[inherit] pointer-events-none z-0 [mask-image:linear-gradient(white,white)] [-webkit-mask-image:-webkit-radial-gradient(white,white)]"
        style={formattedRadius ? { borderRadius: formattedRadius } : undefined}
      >
        {/* Layer 0: Liquid SVG Displaced Wave Background */}
        <div
          className="absolute -inset-10"
          style={{
            backgroundImage: `url("${bgImage}")`,
            backgroundSize: "cover",
            backgroundPosition: bgPosition,
            filter: `url(#${filterId})`,
            transform: "scale(1.1)",
          }}
        />

        {/* Layer 1: Contrast overlay & soft backdrop blur */}
        <div className={cn("absolute inset-0", contrastOverlayClassName)} />

        {/* Layer 2: Ambient Drop Shadow & Subtle Glow */}
        {showOuterShadow && (
          <div
            className="absolute inset-0 rounded-[inherit]"
            style={{
              boxShadow:
                "0 0 40px rgba(0, 0, 0, 0.35), 0 0 20px rgba(255, 255, 255, 0.08)",
              ...(formattedRadius ? { borderRadius: formattedRadius } : {}),
              ...shadowStyle,
            }}
          />
        )}
      </div>

      {/* Layer 3: Specular Inner Border Highlight */}
      {showSpecularHighlight && (
        <div
          className="absolute inset-0 z-40 pointer-events-none rounded-[inherit] border border-white/40 dark:border-white/15"
          style={{
            boxShadow:
              "inset 2px 2px 2px 0 rgba(255, 255, 255, 0.45), inset -2px -2px 2px 0 rgba(255, 255, 255, 0.3)",
            ...(formattedRadius ? { borderRadius: formattedRadius } : {}),
          }}
        />
      )}
    </div>
  );
}

export interface LiquidGlassWrapperProps
  extends React.HTMLAttributes<HTMLDivElement> {
  children?: React.ReactNode;
  className?: string;
  radius?: string | number | boolean;
  bgImage?: string;
  filterId?: string;
  showSpecularHighlight?: boolean;
  contrastOverlayClassName?: string;
  bgPosition?: string;
  showOuterShadow?: boolean;
  shadowStyle?: React.CSSProperties;
}

export const LiquidGlassWrapper = React.forwardRef<
  HTMLDivElement,
  LiquidGlassWrapperProps
>(
  (
    {
      children,
      className,
      style,
      radius,
      bgImage,
      filterId,
      showSpecularHighlight = true,
      contrastOverlayClassName,
      bgPosition,
      showOuterShadow,
      shadowStyle,
      ...props
    },
    ref
  ) => {
    const formattedRadius = formatRadius(radius);

    const wrapperStyle: React.CSSProperties = {
      ...(formattedRadius ? { borderRadius: formattedRadius } : {}),
      ...style,
    };

    return (
      <div
        ref={ref}
        style={wrapperStyle}
        className={cn(
          "relative overflow-hidden isolate [contain:paint] [transform:translateZ(0)]",
          className
        )}
        {...props}
      >
        <LiquidGlassBackground
          radius={radius}
          bgImage={bgImage}
          filterId={filterId}
          showSpecularHighlight={showSpecularHighlight}
          contrastOverlayClassName={contrastOverlayClassName}
          bgPosition={bgPosition}
          showOuterShadow={showOuterShadow}
